#!/usr/bin/env bash
# R216 chain (2026-09-05): depths 5, 3, 2, 1, 6, 7 on the r213b image against the R216 depth-4 MTP0 oracle: strict pair (G2/G3) then ladders per depth.
# (4, 5, 3, 2, 1) a strict MTP pair against the R213 MTP0 oracle (G2/G3), then the c1-c64 ladders (MTP and MTP0). Arg 1: pid to wait for.
set -uo pipefail
out=/mnt/fast-ai/bench-results; S=/home/steve/b70-optimization-lab/experiments/qwen38-27b-b70/scripts; R=/home/steve/b70-optimization-lab/repro
[[ -n "${1:-}" ]] && while kill -0 "$1" 2>/dev/null; do sleep 30; done
oracle=$out/qwen38-int4-gptq-relabel-r187-stack-mtp4-detpad-op-full-20260905-r216
for DEPTH in 5 3 2 1 6 7; do
  STRICT_MTP1_ONLY=1 ORACLE_ROOT=$oracle DEPTH=$DEPTH env VLLM_XPU_DRAFT_LM_HEAD_INT4=0 VLLM_XPU_W4A16_DETERMINISM_PAD_HIGH=0 MODEL_DIR=/mnt/fast-ai/llm-models/qwen3.8-27b-int4-autoround-gptq-relabel MODEL_MANIFEST=$R/qwen38-27b-autoround-int4-b70/manifests/model-gptq-relabel-r212.json QUANTIZATION=${QUANTIZATION:-gptq} VLLM_XPU_FP8_BLOCK_W8A16=0   XPU_OPS_SHA256_OVERRIDE=6a7761930cd8b9e3f67902648ba5aaaf708567cebf70fcedda595d698f26b064 LAYERNORM_SHA256_OVERRIDE=50cf5f4f9c72f679e4318cd3e3e021a844f59ac188a891d9a4f9638188f4bce8 GEMMA_TRITON=0 RMSNORM_TRITON=0 GDN_SPLIT_MIXED=1   COMPILATION_CONFIG='{"cudagraph_mode":"PIECEWISE","cudagraph_capture_sizes":[1],"max_cudagraph_capture_size":1,"splitting_ops":[],"inductor_compile_config":{"combo_kernels":false,"benchmark_combo_kernel":false,"deterministic":true,"triton.autotune_pointwise":false,"benchmark_epilogue_fusion":false}}' IMAGE_OVERRIDE=neural-download/vllm-openai-xpu:qwen38-int4-w4a16-detpad-op-r213b IMAGE_ID_OVERRIDE=sha256:cbdc81afe43c28ccd523f6e858c09146f0a4a667a97082a2f1f44dffa3cb8144   SPECULATIVE_CONFIG="{\"method\":\"qwen3_next_mtp\",\"num_speculative_tokens\":${DEPTH:-4}}" ROOT=$out/qwen38-int4-gptq-relabel-r187-stack-mtp${DEPTH}-strict-20260905-r216 bash $S/run-20260902-qwen38-fp8-triton-rmsnorm-r152.sh
  LADDERS_ONLY=1 DEPTH=$DEPTH env VLLM_XPU_DRAFT_LM_HEAD_INT4=0 VLLM_XPU_W4A16_DETERMINISM_PAD_HIGH=0 MODEL_DIR=/mnt/fast-ai/llm-models/qwen3.8-27b-int4-autoround-gptq-relabel MODEL_MANIFEST=$R/qwen38-27b-autoround-int4-b70/manifests/model-gptq-relabel-r212.json QUANTIZATION=${QUANTIZATION:-gptq} VLLM_XPU_FP8_BLOCK_W8A16=0   XPU_OPS_SHA256_OVERRIDE=6a7761930cd8b9e3f67902648ba5aaaf708567cebf70fcedda595d698f26b064 LAYERNORM_SHA256_OVERRIDE=50cf5f4f9c72f679e4318cd3e3e021a844f59ac188a891d9a4f9638188f4bce8 GEMMA_TRITON=0 RMSNORM_TRITON=0 GDN_SPLIT_MIXED=1   COMPILATION_CONFIG='{"cudagraph_mode":"PIECEWISE","cudagraph_capture_sizes":[1],"max_cudagraph_capture_size":1,"splitting_ops":[],"inductor_compile_config":{"combo_kernels":false,"benchmark_combo_kernel":false,"deterministic":true,"triton.autotune_pointwise":false,"benchmark_epilogue_fusion":false}}' IMAGE_OVERRIDE=neural-download/vllm-openai-xpu:qwen38-int4-w4a16-detpad-op-r213b IMAGE_ID_OVERRIDE=sha256:cbdc81afe43c28ccd523f6e858c09146f0a4a667a97082a2f1f44dffa3cb8144   SPECULATIVE_CONFIG="{\"method\":\"qwen3_next_mtp\",\"num_speculative_tokens\":${DEPTH:-4}}" ROOT=$out/qwen38-int4-gptq-relabel-r187-stack-mtp${DEPTH}-ladders-20260905-r216 bash $S/run-20260902-qwen38-fp8-triton-rmsnorm-r152.sh
